// Eine Rechnung aus dem PDF-Text lesen.
// Regel wie in der Python-Fassung: eindeutig umwandeln, sonst abbrechen.
// Jede Fehlermeldung nennt die Datei, sonst sucht man sich spaeter tot.

const datei = $('Read/Write Files from Disk').item.binary?.data?.fileName ?? 'unbekannt';

function fail(msg) {
  throw new Error(`${datei}: ${msg}`);
}

function amount(text) {
  // Deutsche Schreibweise: Punkt gruppiert Tausender, Komma trennt Dezimalen.
  const cleaned = String(text).trim();
  if (!/^\d{1,3}(\.\d{3})*(,\d+)?$|^\d+(,\d+)?$/.test(cleaned)) {
    fail(`kein wohlgeformter Betrag: "${text}"`);
  }
  return parseFloat(cleaned.replace(/\./g, '').replace(',', '.'));
}

function need(re, text, field) {
  const m = text.match(re);
  if (!m) fail(`${field} nicht gefunden - Layout hat sich vermutlich geaendert`);
  return m[1].trim();
}

const text = $json.text;

// Ein Adapter pro Layout. Unbekanntes Dokument wird abgelehnt, nicht geraten.
if (!/MUSTERFIRMA/i.test(text)) {
  fail('unbekanntes Layout - kein Adapter fuer diesen Lieferanten');
}

const number   = need(/Rechnung Nr\.\s*(\S+)/, text, 'Rechnungsnummer');
const dateText = need(/Rechnungsdatum:\s*(\S+)/, text, 'Rechnungsdatum');
const customer = need(/Kunde:\s*(.+)/, text, 'Kunde');

// Datum nur im ausdruecklich erwarteten Format - nicht raten lassen.
const dm = dateText.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
if (!dm) fail(`Datum "${dateText}" ist nicht tt.mm.jjjj`);
const date = `${dm[3]}-${dm[2]}-${dm[1]}`;

let net = null, vat = null, gross = null;
const items = [];

for (const raw of text.split('\n')) {
  const line = raw.trim();
  if (!line || line.startsWith('Position ')) continue;

  let m;
  if ((m = line.match(/^Gesamtbetrag netto\s+([\d.,]+)$/))) { net = amount(m[1]); continue; }
  if ((m = line.match(/^zzgl\..*?\s+([\d.,]+)$/)))          { vat = amount(m[1]); continue; }
  if ((m = line.match(/^Rechnungsbetrag\s+([\d.,]+)$/)))    { gross = amount(m[1]); continue; }

  if ((m = line.match(/^(.+?)\s+(\d+)\s+([\d.,]+)\s+([\d.,]+)$/))) {
    items.push({
      beschreibung: m[1].trim(),
      menge: parseInt(m[2], 10),
      einzelpreis: amount(m[3]),
      summe: amount(m[4]),
    });
  }
}

for (const [value, label] of [[net, 'Nettosumme'], [vat, 'MwSt'], [gross, 'Bruttosumme']]) {
  if (value === null) fail(`${label} fehlt in Rechnung ${number}`);
}

// Gegenprobe: Positionen muessen die Nettosumme ergeben.
const sum = Math.round(items.reduce((a, i) => a + i.summe, 0) * 100) / 100;

return {
  json: {
    datei,
    rechnungsnummer: number,
    datum: date,
    kunde: customer,
    netto: net,
    mwst: vat,
    brutto: gross,
    positionen: items.length,
    positionssumme: sum,
    stimmig: Math.abs(sum - net) < 0.01,
    items,
  },
};

// Aus jeder Rechnung wird je Position eine eigene Zeile.
// Rechnungsnummer, Datum und Kunde wandern mit, damit jede Zeile
// fuer sich lesbar ist und man sie spaeter zuordnen kann.
const zeilen = [];

for (const entry of $input.all()) {
  const r = entry.json;
  for (const pos of r.items ?? []) {
    zeilen.push({
      json: {
        rechnungsnummer: r.rechnungsnummer,
        datum: r.datum,
        kunde: r.kunde,
        beschreibung: pos.beschreibung,
        menge: pos.menge,
        einzelpreis: pos.einzelpreis,
        summe: pos.summe,
      },
    });
  }
}

if (zeilen.length === 0) {
  throw new Error('keine Positionen gefunden - kamen die Rechnungen ohne Einzelposten?');
}

return zeilen;

// Eine Zeile je Rechnung, ohne die verschachtelten Positionen.
// Modus "All Items": wir bekommen den ganzen Stapel und geben eine Liste zurueck.
return $input.all().map(entry => {
  const { items, ...kopf } = entry.json;
  return { json: kopf };
});

// Den Dateinamen direkt beim Lese-Knoten holen, nicht aus der Meldung parsen.
// n8n kann den zugehoerigen Eintrag nur im Each-Item-Modus zuordnen.
let datei = 'unbekannt';
try {
  datei = $('Read/Write Files from Disk').item.binary?.data?.fileName ?? 'unbekannt';
} catch (e) {
  // Zuordnung nicht aufloesbar - dann bleibt es bei "unbekannt"
}

const roh = $json.error;
let problem = typeof roh === 'string' ? roh : (roh?.message ?? JSON.stringify(roh));

// n8n haengt eine interne Zeilennummer an - fuer eine Pruefliste unbrauchbar.
problem = problem.replace(/\s*\[line \d+\]\s*$/, '');

// Falls die Meldung den Dateinamen doch mitbringt, nicht doppelt schreiben.
if (problem.startsWith(datei + ': ')) {
  problem = problem.slice(datei.length + 2);
}

return {
  json: {
    datei,
    problem,
    zeitpunkt: new Date().toISOString(),
  },
};
